/// The web's twenty interface themes, light then dark.
enum ThemeID: String, CaseIterable, Codable, Sendable {
  case classic
  case gulf
  case sky
  case turquoise
  case oasis
  case sand
  case sunset
  case rose
  case lavender
  case graphite
  case midnight
  case deepSea = "deep-sea"
  case lagoon
  case oasisNight = "oasis-night"
  case desertNight = "desert-night"
  case ember
  case roseNight = "rose-night"
  case amethyst
  case charcoal
  case black

  /// Whether the theme is light or dark.
  var scheme: ColorScheme {
    switch self {
    case .classic, .gulf, .sky, .turquoise, .oasis, .sand, .sunset, .rose, .lavender, .graphite: .light
    case .midnight, .deepSea, .lagoon, .oasisNight, .desertNight, .ember, .roseNight, .amethyst, .charcoal, .black: .dark
    }
  }

  /// The theme's name, an English key: show it with `t(theme.nameKey)`.
  var nameKey: String {
    switch self {
    case .classic: "Classic"
    case .gulf: "Gulf blue"
    case .sky: "Sky"
    case .turquoise: "Turquoise"
    case .oasis: "Oasis"
    case .sand: "Desert sand"
    case .sunset: "Sunset"
    case .rose: "Rose"
    case .lavender: "Lavender"
    case .graphite: "Graphite"
    case .midnight: "Midnight"
    case .deepSea: "Deep sea"
    case .lagoon: "Lagoon"
    case .oasisNight: "Oasis night"
    case .desertNight: "Desert night"
    case .ember: "Ember"
    case .roseNight: "Rose night"
    case .amethyst: "Amethyst"
    case .charcoal: "Charcoal"
    case .black: "Black (high contrast)"
    }
  }

  static let lightThemes: [ThemeID] = [.classic, .gulf, .sky, .turquoise, .oasis, .sand, .sunset, .rose, .lavender, .graphite]
  static let darkThemes: [ThemeID] = [.midnight, .deepSea, .lagoon, .oasisNight, .desertNight, .ember, .roseNight, .amethyst, .charcoal, .black]
  static let defaultLight: ThemeID = .classic
  static let defaultDark: ThemeID = .midnight
}

